mapper.insert:
INSERT INTO ingestion_task (
    task_id, owner_id, kb_id, document_id, idempotency_key, task_type,
    status, attempt_count, max_attempts, error_summary,
    created_at, updated_at, started_at, completed_at
) VALUES (
    CAST(#{id} AS uuid), #{ownerId}, CAST(#{kbId} AS uuid), CAST(#{documentId} AS uuid),
    #{idempotencyKey}, #{taskType}, #{status}, #{attemptCount}, #{maxAttempts}, #{errorSummary},
    #{createdAt}, #{updatedAt}, #{startedAt}, #{completedAt}
)
ON CONFLICT (owner_id, idempotency_key) DO NOTHING

mapper.select:
SELECT task_id, owner_id, kb_id, document_id, idempotency_key, task_type,
       status, attempt_count, max_attempts, error_summary,
       created_at, updated_at, started_at, completed_at
FROM ingestion_task
WHERE owner_id = #{ownerId}
  AND idempotency_key = #{idempotencyKey}

SELECT 1
FROM (
    SELECT pg_advisory_xact_lock(
        hashtextextended(CONCAT(#{ownerId}, ':', #{idempotencyKey}), 0)
    )
) lock_guard
